import { readFileSync } from 'node:fs';
import { ok, fail } from './result.js';

const PRODUCTS = JSON.parse(readFileSync(new URL('../data/catalogue.json', import.meta.url), 'utf8'));

/**
 * All products: { sku, name, unitPrice (cents, without VAT), vatRate (percent) }.
 * @returns {Array<{ sku: string, name: string, unitPrice: number, vatRate: number }>}
 */
export function listProducts() {
  return PRODUCTS.map((p) => ({ ...p }));
}

/**
 * One product by SKU.
 * @param {string} sku
 */
export function getProduct(sku) {
  const p = PRODUCTS.find((x) => x.sku === sku);
  return p ? ok({ ...p }) : fail('UNKNOWN_SKU');
}
</file>

<file path="src/credits.js">
import { ok, fail } from './result.js';
import { invoiceTotals } from './invoices.js';

/**
 * Get the next credit note number for a given year.
 * @param {Array<string>} existingNumbers - Array of all issued numbers (invoices and credit notes)
 * @param {string} issueDate - Issue date in YYYY-MM-DD format
 * @returns {{ ok: true, value: string } | { ok: false, error: string }}
 */
function nextCreditNoteNumber(existingNumbers, issueDate) {
  const yearMatch = /^(\d{4})-/.exec(issueDate);
  if (!yearMatch) return fail('DATE_INVALID');
  const year = yearMatch[1];

  const prefix = `CN-${year}-`;
  const counters = existingNumbers
    .filter(num => num.startsWith(prefix))
    .map(num => {
      const counter = num.slice(prefix.length);
      return parseInt(counter, 10);
    })
    .filter(counter => !isNaN(counter));

  const maxCounter = counters.length > 0 ? Math.max(...counters) : 0;
  const nextCounter = maxCounter + 1;

  return ok(`${prefix}${String(nextCounter).padStart(4, '0')}`);
}

/**
 * Create a credit note for an issued invoice (refund).
 * @param {object} invoice - An issued, partially paid, or paid invoice
 * @param {{ amount: number, reason: string, date: string }} params
 * @param {Array<string>} existingNumbers - Array of all issued invoice and credit note numbers
 * @returns {{ ok: true, value: { number: string, invoiceNumber: string, customerId: string, amount: number, reason: string, date: string } } | { ok: false, error: string }}
 */
export function createCreditNote(invoice, { amount, reason, date }, existingNumbers) {
  // Check invoice status is issued, partially_paid, or paid
  if (!['issued', 'partially_paid', 'paid'].includes(invoice.status)) {
    return fail('NOT_ISSUED');
  }

  // Validate amount is a positive integer
  if (!Number.isInteger(amount) || amount <= 0) {
    return fail('AMOUNT_INVALID');
  }

  // Check credit amount doesn't exceed invoice total
  const totals = invoiceTotals(invoice);
  if (amount > totals.total) {
    return fail('CREDIT_TOO_HIGH');
  }

  // Get next credit note number
  const numberResult = nextCreditNoteNumber(existingNumbers, date);
  if (!numberResult.ok) return fail(numberResult.error);

  return ok({
    number: numberResult.value,
    invoiceNumber: invoice.number,
    customerId: invoice.customerId,
    amount,
    reason,
    date,
  });
}
</file>

<file path="src/customers.js">
import { readFileSync } from 'node:fs';
import { ok, fail } from './result.js';

const CUSTOMERS = JSON.parse(readFileSync(new URL('../data/customers.json', import.meta.url), 'utf8'));

/**
 * Discount percentages by customer tier.
 * @type {{ gold: number, silver: number, standard: number }}
 */
export const TIER_DISCOUNTS = {
  gold: 5,
  silver: 2.5,
  standard: 0,
};

/**
 * Normalize a customer ID: trim whitespace and convert to uppercase.
 * @param {string} id
 * @returns {string}
 */
export function normalizeId(id) {
  return String(id).trim().toUpperCase();
}

/**
 * All customers: { id, name, email, country, tier }.
 */
export function listCustomers() {
  return CUSTOMERS.map((c) => ({ ...c }));
}

/**
 * One customer by id (normalized).
 * @param {string} id
 */
export function getCustomer(id) {
  const normalizedId = normalizeId(id);
  const c = CUSTOMERS.find((x) => x.id === normalizedId);
  return c ? ok({ ...c }) : fail('CUSTOMER_NOT_FOUND');
}

/**
 * Check a customer record before it is stored.
 * @param {{ id?: string, name?: string, email?: string }} c
 */
export function validateCustomer(c) {
  if (!c || !c.id || !c.name || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(c.email ?? '')) return fail('CUSTOMER_INVALID');
  return ok({ ...c });
}
</file>

<file path="src/dates.js">
/**
 * Check if a string is a valid date in YYYY-MM-DD format.
 * @param {string} dateStr
 * @returns {boolean}
 */
export function isValidDate(dateStr) {
  // Check format YYYY-MM-DD
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) return false;

  // Parse and validate in UTC
  const date = new Date(dateStr + 'T00:00:00Z');
  const [year, month, day] = dateStr.split('-').map(Number);

  return date.getUTCFullYear() === year &&
         date.getUTCMonth() + 1 === month &&
         date.getUTCDate() === day;
}

/**
 * Add n days to a date string (YYYY-MM-DD), returning a new date string.
 * All operations are done in UTC.
 * @param {string} date - Date string in YYYY-MM-DD format
 * @param {number} n - Number of days to add (can be negative)
 * @returns {string} New date string in YYYY-MM-DD format
 */
export function addDays(date, n) {
  const d = new Date(date + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + n);

  const year = d.getUTCFullYear();
  const month = String(d.getUTCMonth() + 1).padStart(2, '0');
  const day = String(d.getUTCDate()).padStart(2, '0');

  return `${year}-${month}-${day}`;
}

/**
 * Calculate the number of days between two dates (b - a), in whole days.
 * All operations are done in UTC.
 * @param {string} a - Start date string in YYYY-MM-DD format
 * @param {string} b - End date string in YYYY-MM-DD format
 * @returns {number} Number of whole days (b - a)
 */
export function daysBetween(a, b) {
  const dateA = new Date(a + 'T00:00:00Z');
  const dateB = new Date(b + 'T00:00:00Z');

  const diffMs = dateB - dateA;
  return Math.floor(diffMs / (1000 * 60 * 60 * 24));
}

/**
 * Get the last day of the month for a given date (YYYY-MM-DD).
 * @param {string} dateStr - Date string in YYYY-MM-DD format
 * @returns {string} Last day of the month in YYYY-MM-DD format
 */
export function getLastDayOfMonth(dateStr) {
  const [year, month] = dateStr.split('-').map(Number);
  const lastDayNum = new Date(Date.UTC(year, month, 0)).getUTCDate();
  return `${year}-${String(month).padStart(2, '0')}-${String(lastDayNum).padStart(2, '0')}`;
}
</file>

